def reverseVowels(s):
    vowels = set("aeiouAEIOU")
    a = list(s)
    i, j = 0, len(a) - 1
    while i < j:
        if a[i] not in vowels:
            i += 1
        elif a[j] not in vowels:
            j -= 1
        else:
            a[i], a[j] = a[j], a[i]
            i += 1
            j -= 1
    return "".join(a)
